{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.Zouk_Inventory_Capital_Report AS WITH Combined_Inv AS ( SELECT DATETIME(TIMESTAMP(timestamp), \"Asia/Kolkata\") AS DATA_FETCH_DATE, REPLACE(SKUCODE, \'\\'\', \'\') AS SKU, FACILITY AS LOCATION, INVENTORY AS AVAILABLE_INVENTORY, ROW_NUMBER() OVER ( PARTITION BY FACILITY, REPLACE(SKUCODE, \'\\'\', \'\'), CAST(DATETIME(TIMESTAMP(timestamp), \"Asia/Kolkata\") AS DATE) ORDER BY DATETIME(TIMESTAMP(timestamp), \"Asia/Kolkata\") DESC ) AS rw, \'Finished Goods\' AS Type_Of_Inventory FROM MAPLEMONK.UNICOMMERCE_ZOUK_UC_GET_INVENTORY_SNAPSHOT UNION ALL SELECT DATA_FETCH_DATE, REPLACE(SKU, \' \', \'\') AS SKU, TRIM(LOWER(channel)) AS LOCATION, Available_Inventory AS AVAILABLE_INVENTORY, 1 AS rw, \'EBO Inventory\' AS Type_Of_Inventory FROM MapleMonk.ZOUK_STORE_INVENTORY_FACT_ITEMS WHERE TRIM(LOWER(channel)) IS NOT NULL UNION ALL SELECT DATETIME(TIMESTAMP(CAST(Data_Updated_Date AS DATE)), \"Asia/Kolkata\") AS DATA_FETCH_DATE, REPLACE(Item_ID, \' \', \'\') AS SKU, Sub_con_Vendor_Name as LOCATION, SUM((SAFE_CAST(Estimated_Quantity AS INT64) - SAFE_CAST(Quantity_Produced AS INT64))) AS AVAILABLE_INVENTORY, 1 AS rw, \'WIP\' AS Type_Of_Inventory FROM MapleMonk.Zouk_S3_TranZact_WIP GROUP BY 1,2,3 UNION ALL SELECT Inventory_Date AS DATA_FETCH_DATE, REPLACE(RM_SKU, \' \', \'\') AS SKU, Location AS LOCATION, Stock_Available AS AVAILABLE_INVENTORY, 1 AS rw, \'Raw Material\' AS Type_Of_Inventory FROM `MapleMonk.Zouk_Tranzact_Inventory_Table` ), Filtered_Combined AS ( SELECT * FROM Combined_Inv WHERE rw = 1 ) , SKU_Master AS ( SELECT CI.*, SM.commonsku, SM.category, SM.category_code, SM.collection, SM.name FROM Filtered_Combined CI LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY LOWER(commonsku) ORDER BY 1) AS rw FROM `MAPLEMONK.FINAL_SKU_MASTER` ) WHERE rw = 1 ) SM ON LOWER(CI.SKU) = LOWER(SM.commonsku) ) SELECT SM.*, BOM.cogs AS WIP_COGS, CASE WHEN SM.Type_Of_Inventory IN (\'Finished Goods\', \'EBO Inventory\') THEN CAT.cogs ELSE NULL END AS FG_EBO_COGS, RMI.Stock_Value AS RM_Stock_Value FROM SKU_Master SM LEFT JOIN ( SELECT PARSE_DATE(\'%Y-%m-%d\', START_DATE) AS START_DATE, PARSE_DATE(\'%Y-%m-%d\', END_DATE) AS END_DATE, TRIM(LOWER(Category_code)) AS category_code, CAST(REPLACE(BOM_Value, \',\', \'\') AS FLOAT64) AS cogs FROM MapleMonk.Zouk_BOM QUALIFY ROW_NUMBER() OVER (PARTITION BY START_DATE, END_DATE, LOWER(category_code) ORDER BY 1) = 1 ) BOM ON SM.Type_Of_Inventory = \'WIP\' AND DATE(SM.DATA_FETCH_DATE) BETWEEN BOM.START_DATE AND BOM.END_DATE AND LOWER(SM.category_code) = BOM.category_code LEFT JOIN ( SELECT PARSE_DATE(\'%d-%b-%y\', START_DATE) AS START_DATE, PARSE_DATE(\'%d-%b-%y\', END_DATE) AS END_DATE, TRIM(LOWER(category_code)) AS category_code, CAST(REPLACE(cogs, \',\', \'\') AS FLOAT64) AS cogs FROM MapleMonk.zouk_db_sku_mrp_cogs QUALIFY ROW_NUMBER() OVER (PARTITION BY START_DATE, END_DATE, LOWER(category_code) ORDER BY 1) = 1 ) CAT ON DATE(SM.DATA_FETCH_DATE) BETWEEN CAT.START_DATE AND CAT.END_DATE AND LOWER(SM.category_code) = CAT.category_code LEFT JOIN ( SELECT Inventory_Date AS DATA_FETCH_DATE, RM_SKU AS SKU, Location AS LOCATION, SUM(SAFE_CAST(Stock_Value AS FLOAT64)) AS Stock_Value FROM `MapleMonk.Zouk_Tranzact_Inventory_Table` GROUP BY 1, 2, 3 ) RMI ON DATE(SM.DATA_FETCH_DATE) = DATE(RMI.DATA_FETCH_DATE) AND LOWER(SM.SKU) = LOWER(RMI.SKU) AND LOWER(SM.LOCATION) = LOWER(RMI.LOCATION)",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            